insert into ebd.biblia_versiculos (traducao_id, livro_numero, livro, livro_abreviado, capitulo, versiculo, texto)
values
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 11, 3, 'De entre os animais, todo o de casco, e que tem as unhas fendidas, e que rumina, este comereis.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 11, 4, 'Estes, porém, não comereis dos que ruminam e dos que têm casco: o camelo, porque rumina mas não tem casco fendido, haveis de tê-lo por impuro;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 11, 5, 'Também o coelho, porque rumina, mas não tem unha fendida, o tereis por impuro;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 11, 6, 'Assim a lebre, porque rumina, mas não tem unha fendida, a tereis por impura;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 11, 7, 'Também o porco, porque tem unhas, e é de unhas fendidas, mas não rumina, o tereis por impuro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 11, 8, 'Da carne deles não comereis, nem tocareis seu corpo morto: os tereis por impuros.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 11, 9, 'Isto comereis de todas as coisas que estão nas águas: todas as coisas que têm barbatanas e escamas nas águas do mar, e nos rios, aquelas comereis;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 11, 10, 'Mas todas as coisas que não têm barbatanas nem escamas no mar e nos rios, tanto de todo réptil de água como de toda coisa vivente que está nas águas, as tereis em abominação.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 11, 11, 'Vos serão, pois, em abominação: de sua carne não comereis, e abominareis seus corpos mortos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 11, 12, 'Tudo o que não tiver barbatanas e escamas nas águas, o tereis em abominação.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 11, 13, 'E das aves, estas tereis em abominação; não se comerão, serão abominação: a água, o quebra-ossos, o esmerilhão,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 11, 14, 'O milhafre, e o falcão a segundo sua espécie;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 11, 15, 'Todo corvo segundo sua espécie;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 11, 16, 'O avestruz, e a coruja, e a gaivota, e o gavião segundo sua espécie;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 11, 17, 'E o mocho, e o corvo-marinho, e o íbis,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 11, 18, 'E a galinha-d''água, e o cisne, e o pelicano,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 11, 19, 'E a cegonha, e a garça, segundo sua espécie, e a poupa, e o morcego.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 11, 20, 'Todo inseto de asas que andar sobre quatro pés, tereis em abominação.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 11, 21, 'Porém isto comereis de todo inseto de asas que anda sobre quatro patas, que tiver pernas além de suas patas para saltar com elas sobre a terra;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 11, 22, 'Estes comereis deles: o gafanhoto migrador segundo sua espécie, e a esperança segundo sua espécie, e o grilo segundo sua espécie, e o gafanhoto comum segundo sua espécie.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 11, 23, 'Todo réptil de asas que tenha quatro pés, tereis em abominação.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 11, 24, 'E por estas coisas sereis impuros: qualquer um que tocar a seus corpos mortos, será impuro até à tarde:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 11, 25, 'E qualquer um que levar de seus corpos mortos, lavará suas roupas, e será impuro até à tarde.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 11, 26, 'Todo animal de casco, mas que não tem unha fendida, nem rumina, tereis por impuro: qualquer um que os tocar será impuro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 11, 27, 'E de todos os animais que andam a quatro patas, tereis por impuro qualquer um que ande sobre suas garras: qualquer um que tocar seus corpos mortos, será impuro até à tarde.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 11, 28, 'E o que levar seus corpos mortos, lavará suas roupas, e será impuro até à tarde: haveis de tê-los por impuros.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 11, 29, 'E estes tereis por impuros dos répteis que vão arrastando sobre a terra: a doninha, e o rato, e o lagarto segundo sua espécie,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 11, 30, 'E a lagartixa, e o lagarto pintado, e a lagartixa de parede, e a salamandra, e o camaleão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 11, 31, 'Estes tereis por impuros de todos os répteis: qualquer um que os tocar, quando estiverem mortos, será impuro até à tarde.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 11, 32, 'E tudo aquilo sobre que cair algum deles depois de mortos, será impuro; tanto vaso de madeira, como roupa, ou pele, ou saco, qualquer instrumento com que se faz obra, será posto em água, e será impuro até à tarde, e assim será limpo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 11, 33, 'E toda vasilha de barro dentro da qual cair algum deles, tudo o que estiver nela será impuro, e quebrareis a vasilha:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 11, 34, 'Toda comida que se come, sobre a qual vier a água de tais vasilhas, será imunda: e toda bebida que se beber, será em todas essas vasilhas impura:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 11, 35, 'E tudo aquilo sobre que cair algo do corpo morto deles, será impuro: o forno ou aquecedores se derrubarão; são impuros, e por impuros os tereis.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 11, 36, 'Contudo, a fonte e a cisterna onde se recolhem águas, serão limpas: mas o que houver tocado em seus corpos mortos será impuro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 11, 37, 'E se cair de seus corpos mortos sobre alguma semente que se haja de semear, será limpa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 11, 38, 'Mas se se houver posto água na semente, e cair de seus corpos mortos sobre ela, a tereis por impura.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 11, 39, 'E se algum animal que tiverdes para comer se morrer, o que tocar seu corpo morto será impuro até à tarde:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 11, 40, 'E o que comer de seu corpo morto, lavará suas roupas, e será impuro até à tarde: também o que tirar seu corpo morto, lavará suas roupas, e será impuro até à tarde.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 11, 41, 'E todo réptil que vai arrastando sobre a terra, é abominação; não se comerá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 11, 42, 'Tudo o que anda sobre o peito, e tudo o que anda sobre quatro ou mais patas, de todo réptil que anda arrastando sobre a terra, não o comereis, porque é abominação.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 11, 43, 'Não torneis abomináveis vossas pessoas com nenhum réptil que anda arrastando, nem vos contamineis com eles, nem sejais impuros por eles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 11, 44, 'Pois que eu sou o SENHOR vosso Deus, vós portanto vos santificareis, e sereis santos, porque eu sou santo: assim que não torneis abomináveis vossas pessoas com nenhum réptil que andar arrastando sobre a terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 11, 45, 'Porque eu sou o SENHOR, que vos faço subir da terra do Egito para vos ser por Deus: sereis pois santos, porque eu sou santo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 11, 46, 'Esta é a lei dos animais e das aves, e de todo ser vivente que se move nas águas, e de todo animal que anda arrastando sobre a terra;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 11, 47, 'Para fazer diferença entre impuro e limpo, e entre os animais que se podem comer e os animais que não se podem comer.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 12, 1, 'E falou o SENHOR a Moisés, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 12, 2, 'Fala aos filhos de Israel, dizendo: A mulher quando conceber e der à luz macho, será impura sete dias; conforme os dias que está separada por sua menstruação, será impura.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 12, 3, 'E ao oitavo dia circuncidará a carne de seu prepúcio.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 12, 4, 'Mas ela permanecerá trinta e três dias no sangue de sua purificação: nenhuma coisa santa tocará, nem virá ao santuário, até que sejam cumpridos os dias de sua purificação.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 12, 5, 'E se der à luz fêmea será impura duas semanas, conforme sua separação, e sessenta e seis dias estará purificando-se de seu sangue.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 12, 6, 'E quando os dias de sua purificação forem cumpridos, por filho ou por filha, trará um cordeiro de ano para holocausto, e um pombinho ou uma rolinha para expiação, à porta do tabernáculo do testemunho, ao sacerdote:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 12, 7, 'E ele oferecerá diante do SENHOR, e fará expiação por ela, e será limpa do fluxo de seu sangue. Esta é a lei da que der à luz macho ou fêmea.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 12, 8, 'E se não alcançar sua mão o suficiente para um cordeiro, tomará então duas rolinhas ou dois pombinhos, um para holocausto, e outro para expiação: e o sacerdote fará expiação por ela, e será limpa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 13, 1, 'E falou o SENHOR a Moisés e a Arão, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 13, 2, 'Quando o homem tiver na pele de sua carne inchaço, ou pústula, ou mancha branca, e houver na pele de sua carne como chaga de lepra, será trazido a Arão o sacerdote, ou a um dos sacerdotes seus filhos:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 13, 3, 'E o sacerdote olhará a chaga na pele da carne: se o pelo na chaga se tornou branco, e parecer a chaga mais profunda que a pele da carne, chaga de lepra é; e o sacerdote lhe reconhecerá, e lhe dará por impuro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 13, 4, 'E se na pele de sua carne houver mancha branca, mas não parecer mais profunda que a pele, nem seu pelo se houver tornado branco, então o sacerdote encerrará ao que tem chagas por sete dias;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 13, 5, 'E ao sétimo dia o sacerdote o olhará; e se a chaga a seu parecer se houver parado, não havendo-se estendido na pele, então o sacerdote lhe voltará a encerrar por outros sete dias.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 13, 6, 'E ao sétimo dia o sacerdote lhe reconhecerá de novo; e se parece haver-se escurecido a chaga, e que não estendeu na pele, então o sacerdote o dará por limpo: era pústula; e lavará suas roupas, e será limpo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 13, 7, 'Mas se houver ido crescendo a pústula na pele, depois que foi mostrado ao sacerdote para ser limpo, será visto outra vez pelo sacerdote:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 13, 8, 'E se reconhecendo-o o sacerdote, vê que a pústula cresceu na pele, o sacerdote o dará por impuro: é lepra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 13, 9, 'Quando houver chaga de lepra no homem, será trazido ao sacerdote;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 13, 10, 'E o sacerdote olhará, e se parecer inchaço branco na pele, o qual tenha mudado a cor do pelo, e se descobre também a carne viva,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 13, 11, 'Lepra é envelhecida na pele de sua carne; e lhe dará por impuro o sacerdote, e não lhe encerrará, porque é impuro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 13, 12, 'Mas se brotar a lepra estendendo pela pele, e ela cobrir toda a pele do que tem chagas desde sua cabeça até seus pés, a toda vista de olhos do sacerdote;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 13, 13, 'Então o sacerdote lhe reconhecerá; e se a lepra houver coberto toda sua carne, dará por limpo ao que tem chagas: tornou-se toda ela branca; e ele é limpo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 13, 14, 'Mas o dia que parecer nele a carne viva, será impuro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 13, 15, 'E o sacerdote olhará a carne viva, e o dará por impuro. É impura a carne viva: é lepra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 13, 16, 'Mas quando a carne viva se mudar e tornar branca, então virá ao sacerdote;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 13, 17, 'E o sacerdote olhará, e se a chaga se houver tornado branca, o sacerdote dará por limpo ao que tinha a chaga, e será limpo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 13, 18, 'E quando na carne, em sua pele, houver úlcera, e se sarar,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 13, 19, 'E suceder no lugar da úlcera inchaço branco, ou mancha branca avermelhada, será mostrado ao sacerdote:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 13, 20, 'E o sacerdote olhará; e se parecer estar mais baixa que sua pele, e seu pelo se houver tornado branco, o dará o sacerdote por impuro: é chaga de lepra que se originou na úlcera.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 13, 21, 'E se o sacerdote a considerar, e não parecer nela pelo branco, nem estiver mais baixa que a pele, mas sim escura, então o sacerdote o encerrará por sete dias:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 13, 22, 'E se se for estendendo pela pele, então o sacerdote o dará por impuro: é chaga.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 13, 23, 'Porém se a mancha branca estiver em seu lugar, que não tenha estendido, é a cicatriz da úlcera; e o sacerdote o dará por limpo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 13, 24, 'Assim quando a carne tiver em sua pele queimadura de fogo, e houver no sarado do fogo mancha esbranquiçada, avermelhada ou branca,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 13, 25, 'O sacerdote a olhará; e se o pelo se houver tornado branco na mancha, e parecer estar mais profunda que a pele, é lepra que saiu na queimadura; e o sacerdote declarará ao sujeito impuro, por ser chaga de lepra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 13, 26, 'Mas se o sacerdote a olhar, e não parecer na mancha pelo branco, nem estiver mais baixa que a pele, mas sim que está escura, lhe encerrará o sacerdote por sete dias;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 13, 27, 'E ao sétimo dia o sacerdote a reconhecerá: se se houver ido estendendo pela pele, o sacerdote o dará por impuro: é chaga de lepra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 13, 28, 'Porém se a mancha estiver em seu lugar, e não se houver estendido na pele, a não ser que está escura, inchaço é da queimadura: o dará o sacerdote por limpo; que sinal da queimadura é.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 13, 29, 'E ao homem ou mulher que lhe sair chaga na cabeça, ou no queixo,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 13, 30, 'O sacerdote olhará a chaga; e se parecer estar mais profunda que a pele, e o pelo nela fora ruivo e fino, então o sacerdote o dará por impuro: é tinha, é lepra da cabeça ou do queixo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 13, 31, 'Mas quando o sacerdote houver olhado a chaga da tinha, e não parecer estar mais profunda que a pele, nem for nela pelo negro, o sacerdote encerrará ao que tem chagas da tinha por sete dias:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 13, 32, 'E ao sétimo dia o sacerdote olhará a chaga: e se a tinha não parecer haver-se estendido, nem houver nela pelo ruivo, nem parecer a tinha mais profunda que a pele,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 13, 33, 'Então o raparão, mas não raparão o lugar da tinha: e encerrará o sacerdote ao que tem a tinha por outros sete dias.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 13, 34, 'E ao sétimo dia olhará o sacerdote a tinha; e se a tinha não houver estendido na pele, nem parecer estar mais profunda que a pele, o sacerdote o dará por limpo; e lavará suas roupas, e será limpo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 13, 35, 'Porém se a tinha se houver ido estendendo na pele depois de sua purificação,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 13, 36, 'Então o sacerdote a olhará; e se a tinha houver estendido na pele, não busque o sacerdote o pelo ruivo, é impuro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 13, 37, 'Mas se lhe parecer que a tinha está detida, e que saiu nela o pelo negro, a tinha está sarada; ele está limpo, e por limpo o dará o sacerdote.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 13, 38, 'Também o homem ou mulher, quando na pele de sua carne tiver machas, machas brancas,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 13, 39, 'O sacerdote olhará: e se na pele de sua carne parecerem machas brancas algo escurecidas, é impigem que brotou na pele, está limpa a pessoa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 13, 40, 'E o homem, quando se lhe cair os cabelos da cabeça, é calvo, mas limpo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 13, 41, 'E se à parte de seu rosto se lhe cair os cabelos da cabeça, é calvo pela frente, mas limpo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 13, 42, 'Mas quando na calva ou na calva da frente houver chaga branca avermelhada, lepra é que brota em sua calva ou em sua calva da frente.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 13, 43, 'Então o sacerdote o olhará, e se parecer a inchaço da chaga branca avermelhada em sua calva ou em sua calva da frente, como o parecer da lepra da pele da carne,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 13, 44, 'Leproso é, é impuro; o sacerdote o dará logo por impuro; em sua cabeça tem sua chaga.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 13, 45, 'E o leproso em quem houver chaga, suas roupas serão derrotados e sua cabeça descoberta, e com o lábio superior coberto proclamará: -Imundo! -Imundo!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 13, 46, 'Durante todo o tempo que a chaga estiver nele será imundo; estará impuro: habitará sozinho; fora do acampamento será sua morada.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 13, 47, 'E quando na roupa houver praga de lepra, em vestido de lã, ou em vestido de linho;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 13, 48, 'Ou na urdidura ou em trama, de linho ou de lã, ou em pele, ou em qualquer obra de pele;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 13, 49, 'E que a praga seja verde, ou vermelha, em roupa ou em pele, ou na urdidura, ou em trama, ou em qualquer obra de pele; praga é de lepra, e se há de mostrar ao sacerdote.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 13, 50, 'E o sacerdote olhará a praga, e encerrará a coisa que tem praga por sete dias.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 13, 51, 'E ao sétimo dia olhará a praga: e se houver estendido a praga na roupa, ou urdidura, ou na trama, ou em pele, ou em qualquer obra que se faz de peles, lepra roedora é a praga; impura será.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 13, 52, 'Será queimada a roupa, ou urdidura ou trama, de lã ou de linho, ou qualquer obra de peles em que houver tal praga; porque lepra roedora é; ao fogo será queimada.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 13, 53, 'E se o sacerdote olhar, e não parecer que a praga se tenha estendido na roupa, ou urdidura, ou na trama, ou em qualquer obra de peles;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 13, 54, 'Então o sacerdote mandará que lavem onde está a praga, e o encerrará outra vez por sete dias.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 13, 55, 'E o sacerdote olhará depois que a praga for lavada; e se parecer que a praga não mudou seu aspecto, ainda que não tenha estendido a praga, impura é; a queimarás ao fogo; corrosão é penetrante, esteja o estragado na face ou no verso daquela coisa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 13, 56, 'Mas se o sacerdote a vir, e parecer que a praga se escureceu depois que foi lavada, a cortará da roupa, ou da pele, ou da urdidura, ou da trama.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 13, 57, 'E se parecer mais no vestido, ou urdidura, ou trama, ou em qualquer coisa de peles, esverdeando nela, queimarás ao fogo aquilo onde estiver a praga.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 13, 58, 'Porém a roupa, ou urdidura, ou trama, ou qualquer coisa de pele que lavares, e que se lhe tirar a praga, se lavará segunda vez, e então será limpa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 13, 59, 'Esta é a lei da praga da lepra da roupa de lã ou de linho, ou da urdidura, ou da trama, ou de qualquer coisa de pele, para que seja dada por limpa ou por impura.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 14, 1, 'E falou o SENHOR a Moisés, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 14, 2, 'Esta será a lei do leproso quando se limpar: Será trazido ao sacerdote:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 14, 3, 'E o sacerdote sairá fora do acampamento; e olhará o sacerdote, e vendo que está sã a praga da lepra do leproso,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 14, 4, 'O sacerdote mandará logo que se tomem para o que se purifica duas aves vivas, limpas, e pau de cedro, e carmesim, e hissopo;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 14, 5, 'E mandará o sacerdote matar uma ave em um vaso de barro sobre águas vivas;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 14, 6, 'Depois tomará a ave viva, e o pau de cedro, e o carmesim, e o hissopo, e o molhará com a ave viva no sangue da ave morta sobre as águas vivas:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 14, 7, 'E espargirá sete vezes sobre o que se purifica da lepra, e lhe dará por limpo; e soltará a ave viva sobre a face do campo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 14, 8, 'E o que se purifica lavará suas roupas, e rapará todos os seus pelos, e se há de lavar com água, e será limpo: e depois entrará no acampamento, e morará fora de sua tenda sete dias.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 14, 9, 'E será, que ao sétimo dia rapará todos os seus pelos, sua cabeça, e sua barba, e as sobrancelhas de seus olhos; finalmente, rapará todo seu pelo, e lavará suas roupas, e lavará sua carne em águas, e será limpo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 14, 10, 'E no oitavo dia tomará dois cordeiros sem defeito, e uma cordeira de ano sem mácula; e três décimos [de efa] de boa farinha para oferta amassada com azeite, e um logue de azeite.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 14, 11, 'E o sacerdote que lhe purifica apresentará com aquelas coisas ao que se há de limpar diante do SENHOR, à porta do tabernáculo do testemunho:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 14, 12, 'E tomará o sacerdote um cordeiro, e o oferecerá pela culpa, com o logue de azeite, e o moverá como oferta movida diante do SENHOR:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 14, 13, 'E degolará o cordeiro no lugar onde degolam o sacrifício pelo pecado e o holocausto, no lugar do santuário: porque como o sacrifício pelo pecado, assim também o sacrifício pela culpa é do sacerdote: é coisa muito sagrada.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 14, 14, 'E tomará o sacerdote do sangue do animal sacrificado pela culpa, e porá o sacerdote sobre a ponta da orelha direita do que se purifica, e sobre o polegar de sua mão direita, e sobre o polegar de seu pé direito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 14, 15, 'Também tomará o sacerdote do logue de azeite, e lançará sobre a palma de sua mão esquerda:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 14, 16, 'E molhará seu dedo direito no azeite que tem em sua mão esquerda, e espargirá do azeite com seu dedo sete vezes diante do SENHOR:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 14, 17, 'E do que restar do azeite que tem em sua mão, porá o sacerdote sobre a ponta da orelha direita do que se purifica, e sobre o polegar de sua mão direita, e sobre o polegar de seu pé direito, sobre o sangue da expiação pela culpa:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 14, 18, 'E o que restar do azeite que tem em sua mão, porá sobre a cabeça do que se purifica: e fará o sacerdote expiação por ele diante do SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 14, 19, 'Oferecerá logo o sacerdote o sacrifício pelo pecado, e fará expiação pelo que se há de purificar de sua impureza, e depois degolará o holocausto:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 14, 20, 'E fará subir o sacerdote o holocausto e a oferta de cereais sobre o altar. Assim fará o sacerdote expiação por ele, e será limpo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 14, 21, 'Mas se for pobre, que não alcançar sua mão a tanto, então tomará um cordeiro para ser oferecido como oferta movida pela culpa, para reconciliar-se, e um décimo [de efa] de boa farinha amassada com azeite para oferta de cereais, e um logue de azeite;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 14, 22, 'E duas rolinhas, ou dois pombinhos, o que alcançar sua mão: e um será para expiação pelo pecado, e o outro para holocausto;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 14, 23, 'As quais coisas trará ao oitavo dia de sua purificação ao sacerdote, à porta do tabernáculo do testemunho diante do SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 14, 24, 'E o sacerdote tomará o cordeiro da expiação pela culpa, e o logue de azeite, e o moverá o sacerdote como oferta movida diante do SENHOR;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 14, 25, 'Logo degolará o cordeiro da culpa, e tomará o sacerdote do sangue da culpa, e porá sobre a ponta da orelha direita do que se purifica, e sobre o polegar de sua mão direita, e sobre o polegar de seu pé direito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 14, 26, 'E o sacerdote lançará do azeite sobre a palma de sua mão esquerda;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 14, 27, 'E com seu dedo direito espargirá o sacerdote do azeite que tem em sua mão esquerda, sete vezes diante do SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 14, 28, 'Também porá o sacerdote do azeite que tem em sua mão sobre a ponta da orelha direita do que se purifica, e sobre o polegar de sua mão direita, e sobre o polegar de seu pé direito, no lugar do sangue da culpa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 14, 29, 'E o que sobrar do azeite que o sacerdote tem em sua mão, o porá sobre a cabeça do que se purifica, para reconciliá-lo diante do SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 14, 30, 'Também oferecerá uma das rolinhas, ou dos pombinhos, o que alcançar sua mão:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 14, 31, 'O um do que alcançar sua mão, em expiação pelo pecado, e o outro em holocausto, ademais da oferta: e fará o sacerdote expiação pelo que se há de purificar, diante do SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 14, 32, 'Esta é a lei do que houver tido praga de lepra, cuja mão não alcançar o prescrito para purificar-se.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 14, 33, 'E falou o SENHOR a Moisés e a Arão, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 14, 34, 'Quando houveres entrado na terra de Canaã, a qual eu vos dou em possessão, e puser eu praga de lepra em alguma casa da terra de vossa possessão,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 14, 35, 'Virá aquele cuja for a casa, e dará aviso ao sacerdote, dizendo: Como praga apareceu em minha casa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 14, 36, 'Então mandará o sacerdote, e despejarão a casa antes que o sacerdote entre a olhar a praga, para que não seja contaminado tudo o que estiver na casa: e depois o sacerdote entrará a reconhecer a casa:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 14, 37, 'E olhará a praga: e se se virem machas nas paredes da casa, cavidades esverdeadas ou vermelhas, as quais parecerem mais profundas que a parede,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 14, 38, 'O sacerdote sairá da casa à porta dela, e fechará a casa por sete dias.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 14, 39, 'E ao sétimo dia voltará o sacerdote, e olhará: e se a praga houver crescido nas paredes da casa,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 14, 40, 'Então mandará o sacerdote, e arrancarão as pedras em que estiver a praga, e as lançarão fora da cidade, em lugar impuro:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 14, 41, 'E fará raspar a casa por dentro ao redor, e derramarão o pó que rasparem fora da cidade em lugar impuro:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 14, 42, 'E tomarão outras pedras, e as porão em lugar das pedras tiradas; e tomarão outro barro, e rebocarão a casa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 14, 43, 'E se a praga voltar a esverdear naquela casa, depois que fez arrancar as pedras, e raspar a casa, e depois que foi rebocada,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 14, 44, 'Então o sacerdote entrará e olhará; e se parecer haver-se estendido a praga na casa, lepra roedora está na casa: impura é.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 14, 45, 'Derrubará, portanto, a tal casa, suas pedras, e seus madeiros, e toda a mistura da casa; e o tirará fora da cidade a lugar impuro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 14, 46, 'E qualquer um que entrar naquela casa todos os dias que a mandou fechar, será impuro até à tarde.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 14, 47, 'E o que dormir naquela casa, lavará suas roupas; também o que comer na casa, lavará suas roupas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 14, 48, 'Mas se entrar o sacerdote e olhar, e vir que a praga não se estendeu na casa depois que foi rebocada, o sacerdote dará a casa por limpa, porque a praga sarou.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 14, 49, 'Então tomará para limpar a casa duas aves, e pau de cedro, e carmesim, e hissopo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 14, 50, 'E degolará uma ave em uma vasilha de barro sobre águas vivas:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 14, 51, 'E tomará o pau de cedro, e o hissopo, e o carmesim, e a ave viva, e o molhará no sangue da ave morta e nas águas vivas, e espargirá a casa sete vezes:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 14, 52, 'E purificará a casa com o sangue da ave, e com as águas vivas, e com a ave viva, e o pau de cedro, e o hissopo, e o carmesim:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 14, 53, 'Logo soltará a ave viva fora da cidade sobre a face do campo: Assim fará expiação pela casa, e será limpa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 14, 54, 'Esta é a lei acerca de toda praga de lepra, e de tinha;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 14, 55, 'E da lepra da roupa, e da casa;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 14, 56, 'E acerca do inchaço, e da pústula, e da mancha branca:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 14, 57, 'Para ensinar quando é impuro, e quando limpo. Esta é a lei tocante à lepra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 15, 1, 'E falou o SENHOR a Moisés e a Arão, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 15, 2, 'Falai aos filhos de Israel, e dizei-lhes: Qualquer homem, quando seu corrimento sair de sua carne, será impuro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 15, 3, 'E esta será sua impureza em seu fluxo; seja que sua carne derramou por causa de seu fluxo, ou que sua carne se obstruiu por causa de seu fluxo, ele será impuro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 15, 4, 'Toda cama em que se deitar o que tiver fluxo, será impura; e toda coisa sobre que se sentar, impura será.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 15, 5, 'E qualquer um que tocar em sua cama, lavará suas roupas; lavará também a si mesmo com água, e será impuro até à tarde.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 15, 6, 'E o que se sentar sobre aquilo em que se houver sentado o que tem fluxo, lavará suas roupas, se lavará também a si mesmo com água, e será impuro até à tarde.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 15, 7, 'Também o que tocar a carne do que tem fluxo, lavará suas roupas, e a si mesmo se lavará com água, e será impuro até à tarde.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 15, 8, 'E se o que tem fluxo cuspir sobre o limpo, este lavará suas roupas, e depois de haver-se lavado com água, será impuro até à tarde.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 15, 9, 'E toda sela sobre que cavalgar o que tiver fluxo, será impura.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 15, 10, 'E qualquer um que tocar qualquer coisa que tenha estado debaixo dele, será impuro até à tarde; e o que a levar, lavará suas roupas, e depois de lavar-se com água, será impuro até à tarde.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 15, 11, 'E todo aquele a quem tocar o que tem fluxo, e não lavar com água suas mãos, lavará suas roupas, e a si mesmo se lavará com água, e será impuro até à tarde.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 15, 12, 'E a vasilha de barro em que tocar o que tem fluxo, será quebrada; e toda vasilha de madeira será lavada com água.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 15, 13, 'E quando se houver limpado de seu fluxo o que tem fluxo, se há de contar sete dias desde sua purificação, e lavará suas roupas, e lavará sua carne em águas vivas, e será limpo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 15, 14, 'E no oitavo dia tomará duas rolinhas, ou dois pombinhos, e virá diante do SENHOR à porta do tabernáculo do testemunho, e os dará ao sacerdote:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 15, 15, 'E os fará o sacerdote, uma oferta pelo pecado, e o outro holocausto: e lhe purificará o sacerdote de seu fluxo diante do SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 15, 16, 'E o homem, quando dele sair derramamento seminal, lavará em águas toda sua carne, e será impuro até à tarde.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 15, 17, 'E toda vestimenta, ou toda pele sobre a qual houver o derramamento seminal, lavará com água, e será impura até à tarde.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 15, 18, 'E a mulher com quem o homem tiver ajuntamento seminal, ambos se lavarão com água, e serão impuros até à tarde.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 15, 19, 'E quando a mulher tiver fluxo de sangue, e seu fluxo for em sua carne, sete dias estará separada; e qualquer um que tocar nela, será impuro até à tarde.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 15, 20, 'E tudo aquilo sobre que ela se deitar durante sua separação, será impuro: também tudo aquilo sobre que se sentar, será impuro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 15, 21, 'E qualquer um que tocar a sua cama, lavará suas roupas, e depois de lavar-se com água, será impuro até à tarde.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 15, 22, 'Também qualquer um que tocar qualquer móvel sobre que ela se houver sentado, lavará suas roupas; lavará logo a si mesmo com água, e será impuro até à tarde.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 15, 23, 'E se estiver sobre a cama, ou sobre a cadeira em que ela se houver sentado, o que tocar nela será impuro até à tarde.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 15, 24, 'E se alguém dormir com ela, e sua menstruação for sobre ele, será impuro por sete dias; e toda cama sobre que dormir, será impura.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 15, 25, 'E a mulher, quando seguir o fluxo de seu sangue por muitos dias fora do tempo de seu costume, ou quando tiver fluxo de sangue mais de seu costume; todo o tempo do fluxo de seu imundícia, será impura como nos dias de seu costume.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 15, 26, 'Toda cama em que dormir todo o tempo de seu fluxo, lhe será como a cama de seu costume; e todo móvel sobre que se sentar, será impuro, como a impureza de seu costume.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 15, 27, 'Qualquer um que tocar em essas coisas será impuro; e lavará suas roupas, e a si mesmo se lavará com água, e será impuro até à tarde.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 15, 28, 'E quando for livre de seu fluxo, se há de contar sete dias, e depois será limpa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 15, 29, 'E o oitavo dia tomará consigo duas rolinhas, ou dois pombinhos, e os trará ao sacerdote, à porta do tabernáculo do testemunho:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 15, 30, 'E o sacerdote fará um oferta pelo pecado, e o outro holocausto; e a purificará o sacerdote diante do SENHOR do fluxo de sua impureza.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 15, 31, 'Assim separareis os filhos de Israel de suas imundícias, a fim de que não morram por suas imundícias, contaminando meu tabernáculo que está entre eles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 15, 32, 'Esta é a lei do que tem fluxo, e do que sai derramamento seminal, vindo a ser impuro por causa disso;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 15, 33, 'E da que padece seu costume, e acerca do que tiver fluxo, seja homem ou fêmea, e do homem que dormir com mulher impura.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 16, 1, 'E falou o SENHOR a Moisés, depois que morreram os dois filhos de Arão, quando se chegaram diante do SENHOR, e morreram;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 16, 2, 'E o SENHOR disse a Moisés: Dize a Arão teu irmão, que não em todo tempo entre no santuário do véu dentro, diante do propiciatório que está sobre a arca, para que não morra: porque eu aparecerei na nuvem sobre o propiciatório.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 16, 3, 'Com isto entrará Arão no santuário: com um bezerro por expiação, e um carneiro em holocausto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 16, 4, 'A túnica santa de linho se vestirá, e sobre sua carne terá calções de linho, e se cingirá o cinto de linho; e com a mitra de linho se cobrirá: são as santas vestiduras: com elas, depois de lavar sua carne com água, se há de vestir.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 16, 5, 'E da congregação dos filhos de Israel tomará dois machos de bode para expiação, e um carneiro para holocausto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 16, 6, 'E fará achegar Arão o bezerro da expiação, que é seu, e fará a reconciliação por si e por sua casa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 16, 7, 'Depois tomará os dois machos de bode, e os apresentará diante do SENHOR à porta do tabernáculo do testemunho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 16, 8, 'E lançará sortes Arão sobre os dois machos de bode; uma sorte pelo SENHOR, e a outra sorte por Azazel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 16, 9, 'E fará achegar Arão o bode macho sobre o qual cair a sorte pelo SENHOR, e o oferecerá em expiação.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 16, 10, 'Mas o bode macho, sobre o qual cair a sorte por Azazel, o apresentará vivo diante do SENHOR, para fazer a reconciliação sobre ele, para enviá-lo a Azazel ao deserto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 16, 11, 'E fará chegar Arão o bezerro que era seu para expiação, e fará a reconciliação por si e por sua casa, e degolará em expiação o bezerro que é seu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 16, 12, 'Depois tomará o incensário cheio de brasas de fogo, do altar de diante do SENHOR, e seus punhos cheios do incenso aromático prensado, e o meterá do véu dentro:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 16, 13, 'E porá o incenso sobre o fogo diante do SENHOR, e a nuvem do incenso cobrirá o propiciatório que está sobre o testemunho, e não morrerá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 16, 14, 'Tomará logo do sangue do bezerro, e espargirá com seu dedo até o propiciatório ao lado oriental: até o propiciatório espargirá sete vezes daquele sangue com seu dedo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 16, 15, 'Depois degolará em expiação o bode macho, que era do povo, e meterá o sangue dele do véu dentro; e fará de seu sangue como fez do sangue do bezerro, e espargirá sobre o propiciatório e diante do propiciatório:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 16, 16, 'E limpará o santuário, das imundícias dos filhos de Israel, e de suas rebeliões, e de todos os seus pecados: da mesma maneira fará também ao tabernáculo do testemunho, o qual reside entre eles em meio de suas imundícias.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 16, 17, 'E nenhum homem estará no tabernáculo do testemunho quando ele entrar a fazer a reconciliação no santuário, até que ele saia, e haja feito a reconciliação por si, e por sua casa, e por toda a congregação de Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 16, 18, 'E sairá ao altar que está diante do SENHOR, e o expiará; e tomará do sangue do bezerro, e do sangue do bode macho, e porá sobre as pontas do altar ao redor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 16, 19, 'E espargirá sobre ele do sangue com seu dedo sete vezes, e o limpará, e o santificará das imundícias dos filhos de Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 16, 20, 'E quando houver acabado de expiar o santuário, e o tabernáculo do testemunho, e o altar, fará chegar o bode macho vivo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 16, 21, 'E porá Arão ambas as mãos suas sobre a cabeça do bode macho vivo, e confessará sobre ele todas as iniquidades dos filhos de Israel, e todas suas rebeliões, e todos os seus pecados, pondo-os assim sobre a cabeça do bode macho, e o enviará ao deserto por meio de um homem destinado para isto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 16, 22, 'E aquele bode macho levará sobre si todas as iniquidades deles a terra inabitada: e deixará ir o bode macho pelo deserto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 16, 23, 'Depois virá Arão ao tabernáculo do testemunho, e se desnudará as vestimentas de linho, que havia vestido para entrar no santuário, e as porá ali.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 16, 24, 'Lavará logo sua carne com água no lugar do santuário, e depois de se pôr suas roupas sairá, e fará seu holocausto, e o holocausto do povo, e fará a reconciliação por si e pelo povo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 16, 25, 'E queimará a gordura da expiação sobre o altar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 16, 26, 'E o que houver levado o bode macho a Azazel, lavará suas roupas, lavará também com água sua carne, e depois entrará no acampamento.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 16, 27, 'E tirará fora do acampamento o bezerro do pecado, e o bode macho da culpa, o sangue dos quais foi metido para fazer a expiação no santuário; e queimarão no fogo suas peles, e suas carnes, e seu excremento.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 16, 28, 'E o que os queimar, lavará suas roupas, lavará também sua carne com água, e depois entrará no acampamento.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 16, 29, 'E isto tereis por estatuto perpétuo: No mês sétimo, aos dez do mês, afligireis vossas almas, e nenhuma obra fareis, nem o natural nem o estrangeiro que peregrina entre vós:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 16, 30, 'Porque neste dia se vos reconciliará para limpar-vos; e sereis limpos de todos vossos pecados diante do SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 16, 31, 'Sábado de repouso é para vós, e afligireis vossas almas, por estatuto perpétuo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 16, 32, 'E fará a reconciliação o sacerdote que for ungido, e cuja mão houver sido cheia para ser sacerdote em lugar de seu pai; e se vestirá as vestimentas de linho, as vestiduras sagradas:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 16, 33, 'E expiará o santuário santo, e o tabernáculo do testemunho; expiará também o altar, e aos sacerdotes, e a todo o povo da congregação.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 16, 34, 'E isto tereis por estatuto perpétuo, para expiar aos filhos de Israel de todos os seus pecados uma vez no ano. E Moisés o fez como o SENHOR lhe mandou.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 17, 1, 'E falou o SENHOR a Moisés, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 17, 2, 'Fala a Arão e a seus filhos, e a todos os filhos de Israel, e dize-lhes: Isto é o que mandou o SENHOR, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 17, 3, 'Qualquer homem da casa de Israel que degolar boi, ou cordeiro, ou cabra, no acampamento, ou fora do acampamento,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 17, 4, 'E não o trouxer à porta do tabernáculo do testemunho, para oferecer oferta ao SENHOR diante do tabernáculo do SENHOR, sangue será imputado ao tal homem: sangue derramou; eliminado será o tal homem dentre seu povo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 17, 5, 'A fim de que tragam os filhos de Israel seus sacrifícios, os que sacrificam sobre a face do campo, para que os tragam ao SENHOR à porta do tabernáculo do testemunho ao sacerdote, e sacrifiquem eles sacrifícios pacíficos ao SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 17, 6, 'E o sacerdote espargirá o sangue sobre o altar do SENHOR, à porta do tabernáculo do testemunho, e queimará a gordura em cheiro suave ao SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 17, 7, 'E nunca mais sacrificarão seus sacrifícios aos demônios, atrás dos quais se prostituíram: terão isto por estatuto perpétuo por suas gerações.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 17, 8, 'Tu Lhes dirás também: Qualquer homem da casa de Israel, ou dos estrangeiros que peregrinam entre vós, que oferecer holocausto ou sacrifício,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 17, 9, 'E não o trouxer à porta do tabernáculo do testemunho, para fazê-lo ao SENHOR, o tal homem será igualmente eliminado de seus povos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 17, 10, 'E qualquer homem da casa de Israel, ou dos estrangeiros que peregrinam entre eles, que comer algum sangue, eu porei meu rosto contra a pessoa que comer sangue, e lhe cortarei dentre seu povo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 17, 11, 'Porque a vida da carne no sangue está: e eu vos a dei para expiar vossas pessoas sobre o altar: pelo qual o mesmo sangue expiará a pessoa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 17, 12, 'Portanto, disse aos filhos de Israel: Nenhuma pessoa de vós comerá sangue, nem o estrangeiro que peregrina entre vós comerá sangue.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 17, 13, 'E qualquer homem dos filhos de Israel, ou dos estrangeiros que peregrinam entre eles, que recolher caça de animal ou de ave que seja de comer, derramará seu sangue e o cobrirá com terra:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 17, 14, 'Porque a alma de toda carne, sua vida, está em seu sangue: portanto disse aos filhos de Israel: Não comereis o sangue de nenhuma carne, porque a vida de toda carne é seu sangue; qualquer um que a comer será eliminado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 17, 15, 'E qualquer um pessoa que comer coisa morta ou despedaçada por fera, tanto dos naturais como dos estrangeiros, lavará suas roupas e a si mesmo se lavará com água, e será impuro até à tarde; e se limpará.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 17, 16, 'E se não os lavar, nem lavar sua carne, levará sua iniquidade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 18, 1, 'E falou o SENHOR a Moisés, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 18, 2, 'Fala aos filhos de Israel, e dize-lhes: Eu sou o SENHOR vosso Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 18, 3, 'Não fareis como fazem na terra do Egito, na qual morastes; nem fareis como fazem na terra de Canaã, à qual eu vos conduzo; nem andareis em seus estatutos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 18, 4, 'Meus regulamentos poreis por obra, e meus estatutos guardareis, andando neles: Eu sou o SENHOR vosso Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 18, 5, 'Portanto meus estatutos e meus regulamentos guardareis, os quais fazendo o homem, viverá neles: Eu sou o SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 18, 6, 'Nenhum homem se achegue a nenhuma próxima de sua carne, para descobrir sua nudez: Eu sou o SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 18, 7, 'A nudez de teu pai, ou a nudez de tua mãe, não descobrirás: tua mãe é, não descobrirá sua nudez.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 18, 8, 'A nudez da mulher de teu pai não descobrirás; é a nudez de teu pai.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 18, 9, 'A nudez de tua irmã, filha de teu pai, ou filha de tua mãe, nascida em casa ou nascida fora, sua nudez não descobrirás.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 18, 10, 'A nudez da filha de teu filho, ou da filha de tua filha, seu nudez não descobrirás, porque é a nudez tua.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 18, 11, 'A nudez da filha da mulher de teu pai, gerada de teu pai, tua irmã é, sua nudez não descobrirás.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 18, 12, 'A nudez da irmã de teu pai não descobrirás: é parente de teu pai.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 18, 13, 'A nudez da irmã de tua mãe não descobrirás: porque parente de tua mãe é.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 18, 14, 'A nudez do irmão de teu pai não descobrirás: não chegarás à sua mulher: é mulher do irmão de teu pai.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 18, 15, 'A nudez de tua nora não descobrirás: mulher é de teu filho, não descobrirás sua nudez.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 18, 16, 'A nudez da mulher de teu irmão não descobrirás: é a nudez de teu irmão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 18, 17, 'A nudez da mulher e de sua filha não descobrirás: não tomarás a filha de seu filho, nem a filha de sua filha, para descobrir sua nudez: são parentes, é maldade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 18, 18, 'Não tomarás mulher juntamente com sua irmã, para fazê-la sua rival, descobrindo sua nudez diante dela em sua vida.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 18, 19, 'E não chegarás à mulher na separação de sua impureza, para descobrir sua nudez.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 18, 20, 'Além disso, não terás ato carnal com a mulher de teu próximo, contaminando-te nela.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 18, 21, 'E não dês de tua descendência para fazê-la passar pelo fogo a Moloque; não contamines o nome de teu Deus: Eu sou o SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 18, 22, 'Não te deitarás com homem como com mulher: é abominação.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 18, 23, 'Nem com nenhum animal terás ajuntamento contaminando-te com ele; nem mulher alguma se porá diante de animal para ajuntar-se com ele: é confusão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 18, 24, 'Em nenhuma destas coisas vos contaminareis; porque em todas estas coisas se poluíram as nações que eu expulso de diante de vós:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 18, 25, 'E a terra foi contaminada; e eu visitei sua maldade sobre ela, e a terra vomitou seus moradores.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 18, 26, 'Guardai, pois, vós meus estatutos e meus regulamentos, e não façais nenhuma de todas estas abominações: nem o natural nem o estrangeiro que peregrina entre vós.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 18, 27, '(Porque todas estas abominações fizeram os homens da terra, que foram antes de vós, e a terra foi contaminada:)'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 18, 28, 'E a terra não vos vomitará, por havê-la contaminado, como vomitou à gente que foi antes de vós.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 18, 29, 'Porque qualquer um que fizer alguma de todas estas abominações, as pessoas que as fizerem, serão eliminadas dentre seu povo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 18, 30, 'Guardai, pois, minha ordenança, não fazendo das práticas abomináveis que tiveram lugar antes de vós, e não vos torneis abomináveis nelas: Eu sou o SENHOR vosso Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 19, 1, 'E falou o SENHOR a Moisés, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 19, 2, 'Fala a toda a congregação dos filhos de Israel, e dize-lhes: Santos sereis, porque santo sou eu o SENHOR vosso Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 19, 3, 'Cada um temerá a sua mãe e a seu pai, e meus sábados guardareis: Eu sou o SENHOR vosso Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 19, 4, 'Não vos voltareis aos ídolos, nem fareis para vós deuses de fundição: Eu sou o SENHOR vosso Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 19, 5, 'E quando sacrificardes sacrifício pacífico ao SENHOR, de vossa vontade o sacrificareis.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 19, 6, 'Será comido o dia que o sacrificardes, e o dia seguinte: e o que restar para o terceiro dia, será queimado no fogo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 19, 7, 'E se se comer no dia terceiro, será abominação; não será aceito:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 19, 8, 'E o que o comer, levará seu delito, porquanto profanou o santo do SENHOR; e a tal pessoa será eliminada de seus povos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 19, 9, 'Quando ceifardes na colheita de vossa terra, não acabarás de ceifar o canto de tua plantação, nem espigarás tua terra ceifada.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 19, 10, 'E não coletarás os restos de tua vinha, nem recolherás as uvas caídas de tua vinha; para o pobre e para o estrangeiro os deixarás: Eu sou o SENHOR vosso Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 19, 11, 'Não furtareis, e não enganareis, nem mentireis ninguém a seu próximo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 19, 12, 'E não jurareis em meu nome com mentira, nem profanarás o nome de teu Deus: Eu sou o SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 19, 13, 'Não oprimirás a teu próximo, nem lhe roubarás. Não se deterá o trabalho do assalariado em tua casa até a manhã.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 19, 14, 'Não amaldiçoes ao surdo, e diante do cego não ponhas tropeço, mas terás temor de teu Deus: Eu sou o SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 19, 15, 'Não farás injustiça no juízo: não favorecerás deslealmente ao pobre, nem honrarás a face do poderoso: com justiça julgarás a teu próximo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 19, 16, 'Não andarás propagando boatos em teus povos. Não te porás contra o sangue de teu próximo: Eu sou o SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 19, 17, 'Não aborrecerás a teu irmão em teu coração: francamente repreenderás a teu próximo, e não consentirás sobre ele pecado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 19, 18, 'Não te vingarás, nem guardarás rancor aos filhos de teu povo: mas amarás a teu próximo como a ti mesmo: Eu sou o SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 19, 19, 'Meus estatutos guardareis. A teu animal não farás ajuntar para espécies misturadas; tua plantação não semearás com mistura de sementes, e não te porás roupas com mistura de diversos materiais.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 19, 20, 'E quando um homem tiver relação sexual com mulher, e ela for serva desposada com alguém, e não estiver resgatada, nem lhe houver sido dada liberdade, ambos serão açoitados: não morrerão, porquanto ela não é livre.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 19, 21, 'E ele trará ao SENHOR, à porta do tabernáculo do testemunho, um carneiro em expiação por sua culpa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 19, 22, 'E com o carneiro da expiação o reconciliará o sacerdote diante do SENHOR, por seu pecado que cometeu: e se lhe perdoará seu pecado que cometeu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 19, 23, 'E quando houverdes entrado na terra, e plantardes toda árvore de comer, tirareis seu prepúcio, o primeiro de seu fruto: três anos vos será incircunciso: seu fruto não se comerá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 19, 24, 'E o quarto ano todo seu fruto será santidade de louvores ao SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 19, 25, 'Mas ao quinto ano comereis o fruto dele, para que vos faça crescer seu fruto: Eu sou o SENHOR vosso Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 19, 26, 'Não comereis coisa alguma com sangue. Não sereis encantadores, nem fareis adivinhações.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 19, 27, 'Não cortareis em redondo as extremidades de vossas cabeças, nem danificarás a ponta de tua barba.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 19, 28, 'E não fareis cortes em vossa carne por um morto, nem imprimireis em vós sinal alguma: Eu sou o SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 19, 29, 'Não contaminarás tua filha fazendo-a se prostituir: para não se prostitua a terra, e se encha de maldade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 19, 30, 'Meus sábados guardareis, e meu santuário tereis em reverência: Eu sou o SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 19, 31, 'Não vos volteis aos encantadores e aos adivinhos: não os consulteis contaminando-vos com eles: Eu sou o SENHOR vosso Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 19, 32, 'Diante das cãs te levantarás, e honrarás o rosto do ancião, e de teu Deus terás temor: Eu sou o SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 19, 33, 'E quando o estrangeiro morar contigo em vossa terra, não o oprimireis.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 19, 34, 'Como a um natural de vós tereis ao estrangeiro que peregrinar entre vós; e ama-o como a ti mesmo; porque peregrinos fostes na terra do Egito: Eu sou o SENHOR vosso Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 19, 35, 'Não façais injustiça no juízo, na medida da terra, nem no peso, nem em outra medida.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 19, 36, 'Balanças justas, pesos justos, efa justo, e him justo tereis. Eu sou o SENHOR vosso Deus, que vos tirei da terra do Egito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 19, 37, 'Guardai, pois, todos os meus estatutos, e todos os meus regulamentos, e os praticai. Eu sou o SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 20, 1, 'E o SENHOR falou a Moisés, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 20, 2, 'Dirás também aos filhos de Israel: Qualquer homem dos filhos de Israel, ou dos estrangeiros que peregrinam em Israel, que oferecer de sua descendência a Moloque, certamente morrerá; o povo da terra o apedrejará.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 20, 3, 'Eu porei o meu rosto contra esse homem, e o eliminarei do meio do seu povo; porque deu de sua descendência a Moloque, contaminando o meu santuário, e profanando o meu santo nome.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 20, 4, 'E, se o povo daquela terra esconder os seus olhos daquele homem que houver dado de sua descendência a Moloque, para não o matar,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 20, 5, 'então eu porei o meu rosto contra aquele homem, e contra a sua família, e o eliminarei do meio do seu povo, com todos os que se prostituem seguindo-o, prostituindo-se com Moloque.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 20, 6, 'Se uma pessoa se voltar aos que consultam os mortos ou aos adivinhos, para se prostituir seguindo-os, eu porei o meu rosto contra aquela pessoa, e a eliminarei do meio do seu povo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 20, 7, 'Santificai-vos, pois, e sede santos, porque eu o SENHOR sou vosso Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 20, 8, 'E guardai meus estatutos, e os praticai. Eu sou o SENHOR que vos santifico.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 20, 9, 'Aquele que amaldiçoar seu pai ou sua mãe certamente morrerá; a seu pai ou a sua mãe amaldiçoou; seu sangue será sobre ele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 20, 10, 'E o homem que adulterar com a mulher de outro, o que cometer adultério com a mulher de seu próximo, certamente se condenará à morte o adúltero e a adúltera.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 20, 11, 'Qualquer um que se deitar com a mulher de seu pai terá revelou a nudez de seu pai; ambos serão mortos; seu sangue será sobre eles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 20, 12, 'Qualquer um que se deitar com a sua nora, ambos terão de morrer; fizeram abominação; seu sangue será sobre eles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 20, 13, 'Qualquer um que se deitar com homem como se fosse com mulher, fizeram abominação entre ambos; terão de ser mortos; seu sangue será sobre eles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 20, 14, 'E o que tomar para si uma mulher e a mãe dela comete depravação; queimarão com fogo ele e elas, para que não haja depravação no meio de vós.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 20, 15, 'Qualquer um que tiver relação sexual com animal será morto; e matareis ao animal.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 20, 16, 'E a mulher que se aproximar de algum animal, para ter relação sexual com ele, à mulher e ao animal matarás; certamente morrerão; seu sangue será sobre eles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 20, 17, 'Qualquer um que tomar a sua irmã, filha de seu pai ou filha de sua mãe, e vir sua nudez, e ela vir a sua, coisa é execrável; portanto serão mortos à vista dos filhos de seu povo; revelou a nudez de sua irmã; levará consigo o seu pecado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 20, 18, 'Qualquer um que se deitar com mulher menstruada, e descobrir sua nudez, descobriu a sua fonte, e ela descobriu a fonte de seu sangue; ambos serão eliminados do meio do seu povo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 20, 19, 'A nudez da irmã de tua mãe, ou da irmã de teu pai, não descobrirás; uma vez que descobriu sua parente, levarão sobresi a sua perversidade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 20, 20, 'E qualquer um que dormir com a mulher do irmão de seu pai, a nudez do irmão de seu pai descobriu; seu pecado levarão; morrerão sem filhos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 20, 21, 'E o que tomar a mulher de seu irmão, é imundícia; a nudez de seu irmão descobriu; sem filhos serão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 20, 22, 'Guardai, pois, todos meus estatutos e todos meus regulamentos, e ponde-os por obra: e não vos vomitará a terra, na qual eu vos introduzo para que habiteis nela.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 20, 23, 'E não andeis nas práticas da gente que eu lançarei de diante de vós: porque eles fizeram todas estas coisas, e os tive em abominação.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 20, 24, 'Porém a vós vos disse: Vós possuireis a terra deles, e eu a darei a vós para que a possuais por herança, terra que flui leite e mel: Eu sou o SENHOR vosso Deus, que vos separei dos povos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 20, 25, 'Portanto, vós fareis diferença entre animal limpo e impuro, e entre ave impura e limpa: e não torneis abomináveis vossas pessoas nos animais, nem nas aves, nem em nenhuma coisa que vai arrastando pela terra, as quais vos separei por impuras.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 20, 26, 'Haveis, pois, de ser para mim santos, porque eu o SENHOR sou santo, e vos separei dos povos, para que sejais meus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 20, 27, 'E o homem ou a mulher em que houver espírito mediúnico ou de adivinhação, terão de ser mortos; os apedrejarão com pedras; seu próprio sangue [será] sobre eles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 21, 1, 'E o SENHOR disse a Moisés: Fala aos sacerdotes filhos de Arão, e dize-lhes que não se contaminem por um morto em seus povos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 21, 2, 'A não ser por seu parente próximo a si, por sua mãe, ou por seu pai, ou por seu filho, ou por seu irmão,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 21, 3, 'ou por sua irmã virgem, a ele próxima, a qual não tenha tido marido, por ela se contaminará.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 21, 4, 'Porque é líder em seu povo, não se contaminará, fazendo-se impuro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 21, 5, 'Não farão calva em sua cabeça, nem raparão a ponta de sua barba, nem em sua carne farão cortes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 21, 6, 'Santos serão a seu Deus, e não profanarão o nome de seu Deus; porque oferecem os fogos do SENHOR e o pão de seu Deus; portanto, serão santos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 21, 7, 'Mulher prostituta ou infame não tomarão: nem tomarão mulher repudiada de seu marido: porque é santo a seu Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 21, 8, 'O santificarás portanto, pois o pão de teu Deus oferece: santo será para ti, porque santo sou eu o SENHOR vosso santificador.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 21, 9, 'E a filha do homem sacerdote, se começar a se prostituir, a seu pai profana: queimada será ao fogo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 21, 10, 'E aquele que é o sumo sacerdote entre seus irmãos, sobre cuja cabeça foi derramado o azeite da unção, e que foi consagrado para usar as vestimentas, não descobrirá sua cabeça, nem rasgará as suas vestes;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 21, 11, 'nem entrará onde haja alguma pessoa morta, nem por seu pai, ou por sua mãe se contaminará.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 21, 12, 'nem sairá do santuário, nem contaminará o santuário de seu Deus; porque a coroa do azeite da unção de seu Deus está sobre ele: Eu sou o SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 21, 13, 'E tomará ele mulher com sua virgindade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 21, 14, 'Viúva, ou repudiada, ou infame, ou prostituta, estas não tomará: mas tomará virgem de seus povos por mulher.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 21, 15, 'E não profanará sua descendência em seus povos; porque eu o SENHOR sou o que os santifico.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 21, 16, 'E o SENHOR falou a Moisés, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 21, 17, 'Fala a Arão, e dize-lhe: O homem de tua semente em suas gerações, no qual houver falta, não se achegará para oferecer o pão de seu Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 21, 18, 'Porque nenhum homem no qual houver falta, se achegará: homem cego, ou coxo, ou rosto mutilado, ou membro deformado,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 21, 19, 'Ou homem no qual houver fratura de pé ou rotura da mão,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 21, 20, 'Ou corcunda, ou anão, ou que tiver visão embaçada, ou que tenha sarna, ou impigem, ou testículo mutilado;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 21, 21, 'Nenhum homem da descendência de Arão sacerdote, no qual houver falta, se achegará para oferecer as ofertas acendidas do SENHOR. Há falta nele; não se achegará a oferecer o pão de seu Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 21, 22, 'O pão de seu Deus, do muito santo e as coisas santificadas, comerá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 21, 23, 'Porém não entrará do véu dentro, nem se achegará ao altar, porquanto há falta nele: e não profanará meu santuário, porque eu o SENHOR sou o que os santifico.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 21, 24, 'E Moisés falou isto a Arão, e a seus filhos, e a todos os filhos de Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 22, 1, 'E falou o SENHOR a Moisés, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 22, 2, 'Dize a Arão e a seus filhos, que se abstenham das coisas santas dos filhos de Israel, e que não profanem meu santo nome no que eles me santificam: Eu sou o SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 22, 3, 'Dize-lhes: Todo homem de toda vossa descendência em vossas gerações que chegar às coisas sagradas, que os filhos de Israel consagram ao SENHOR, tendo imundícia sobre si, de diante de mim será eliminada sua alma: Eu sou o SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 22, 4, 'Qualquer homem da semente de Arão que for leproso, ou padecer fluxo, não comerá das coisas sagradas até que esteja limpo: e o que tocar qualquer coisa impura de cadáver, ou o homem do qual houver saído derramamento de sêmen;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 22, 5, 'Ou o homem que houver tocado qualquer réptil ou inseto, pelo qual será impuro, ou homem pelo qual venha a ser impuro, conforme qualquer imundícia sua;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 22, 6, 'A pessoa que o tocar, será impura até à tarde, e não comerá das coisas sagradas antes que tenha lavado sua carne com água.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 22, 7, 'E quando o sol se puser, será limpo; e depois comerá as coisas sagradas, porque seu pão é.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 22, 8, 'O morto naturalmente nem despedaçado por fera não comerá, para contaminar-se em ele: Eu sou o SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 22, 9, 'Guardem, pois, minha ordenança, e não levem pecado por ele, não seja que assim morram quando a profanarem: Eu sou o SENHOR que os santifico.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 22, 10, 'Nenhum estranho comerá coisa sagrada; o hóspede do sacerdote, nem o empregado, não comerá coisa sagrada.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 22, 11, 'Mas o sacerdote, quando comprar pessoa de seu dinheiro, esta comerá dela, e o nascido em sua casa: estes comerão de seu pão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 22, 12, 'Porém a filha do sacerdote, quando se casar com homem estranho, ela não comerá da oferta das coisas sagradas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 22, 13, 'Porém se a filha do sacerdote for viúva, ou repudiada, e não tiver descendência, e se houver voltado à casa de seu pai, como em sua juventude, comerá do pão de seu pai; mas nenhum estranho coma dele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 22, 14, 'E o que por acidente comer coisa sagrada, acrescentará a ela seu quinto, e o dará ao sacerdote com a coisa sagrada.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 22, 15, 'Não profanarão, pois, as coisas santas dos filhos de Israel, as quais separam para o SENHOR:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 22, 16, 'E não lhes farão levar a iniquidade do pecado, comendo as coisas santas deles: porque eu o SENHOR sou o que os santifico.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 22, 17, 'E falou o SENHOR a Moisés, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 22, 18, 'Fala a Arão e a seus filhos, e a todos os filhos de Israel, e dize-lhes: Qualquer homem da casa de Israel, ou dos estrangeiros em Israel, que oferecer sua oferta por todos os seus votos, e por todas seus ofertas voluntárias que oferecerem ao SENHOR em holocausto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 22, 19, 'De vossa vontade oferecereis macho sem defeito dentre as vacas, dentre os cordeiros, ou dentre as cabras.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 22, 20, 'Nenhuma coisa em que tenha falta oferecereis, porque não será aceito por vós.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 22, 21, 'Também, quando alguém oferecer sacrifício pacífico ao SENHOR para presentear voto, ou oferecendo voluntariamente, seja de vacas ou de ovelhas, sem mácula será aceito; não há de haver nele falta.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 22, 22, 'Cego, ou aleijado, ou mutilado, ou com verruga, ou sarnento ou com impingens, não oferecereis estes ao SENHOR, nem deles poreis oferta acesa sobre o altar do SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 22, 23, 'Boi ou carneiro que tenha de mais ou de menos, poderás oferecer por oferta voluntária; mas por voto não será aceito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 22, 24, 'Ferido ou golpeado, rompido ou cortado, não oferecereis ao SENHOR, nem em vossa terra o fareis.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 22, 25, 'Nem da mão de filho de estrangeiro oferecereis o alimento do vosso Deus de todas estas coisas; porque sua deformidade está nelas; falta há nelas, não serão aceitas por vós.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 22, 26, 'E falou o SENHOR a Moisés, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 22, 27, 'O boi, ou o cordeiro, ou a cabra, quando nascer, sete dias estará mamando de sua mãe: mas desde o oitavo dia em adiante será aceito para oferta de sacrifício acendido ao SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 22, 28, 'E seja boi ou carneiro, não degolareis em um dia a o e a seu filho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 22, 29, 'E quando sacrificardes sacrifício de ação de graças ao SENHOR, de vossa vontade o sacrificareis.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 22, 30, 'No mesmo dia se comerá; não deixareis dele para outro dia: Eu sou o SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 22, 31, 'Guardai pois meus mandamentos, e executai-os: Eu sou o SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 22, 32, 'E não profaneis meu santo nome, e eu me santificarei em meio dos filhos de Israel: Eu sou o SENHOR que vos santifico;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 22, 33, 'Que vos tirei da terra do Egito, para ser vosso Deus: Eu sou o SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 23, 1, 'E falou o SENHOR a Moisés, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 23, 2, 'Fala aos filhos de Israel, e dize-lhes: As solenidades do SENHOR, as quais proclamareis santas convocações, aquelas serão minhas solenidades.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 23, 3, 'Seis dias se trabalhará, e no sétimo dia sábado de repouso será, convocação santa: nenhuma obra fareis; sábado é do SENHOR em todas as vossas habitações.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 23, 4, 'Estas são as solenidades do SENHOR, as convocações santas, às quais convocareis em seus tempos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 23, 5, 'No mês primeiro, aos catorze do mês, entre as duas tardes, páscoa é do SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 23, 6, 'E aos quinze dias deste mês é a solenidade dos pães ázimos ao SENHOR: sete dias comereis pães ázimos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 23, 7, 'O primeiro dia tereis santa convocação: nenhuma obra servil fareis.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 23, 8, 'E oferecereis ao SENHOR sete dias oferta acesa: no sétimo dia será santa convocação; nenhuma obra servil fareis.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 23, 9, 'E falou o SENHOR a Moisés, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 23, 10, 'Fala aos filhos de Israel, e dize-lhes: Quando houverdes entrado na terra que eu vos dou, e ceifardes seu colheita, trareis ao sacerdote um ômer por primícia dos primeiros frutos de vossa colheita;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 23, 11, 'O qual moverá o ômer diante do SENHOR, para que sejais aceitos: o dia seguinte do sábado o moverá o sacerdote.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 23, 12, 'E no dia que oferecerdes o ômer, oferecereis um cordeiro de ano, sem defeito, em holocausto ao SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 23, 13, 'E sua oferta de cereais será dois décimos [de efa] de boa farinha amassada com azeite, oferta acesa ao SENHOR em aroma suavíssimo; e sua libação de vinho, a quarta parte de um him.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 23, 14, 'E não comereis pão, nem grão tostado, nem espiga fresca, até este mesmo dia, até que tenhais oferecido a oferta de vosso Deus; estatuto perpétuo é por vossas gerações em todas as vossas habitações.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 23, 15, 'E vos haveis de contar desde o dia seguinte do sábado, desde o dia em que oferecestes o ômer da oferta movida; sete semanas completas serão:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 23, 16, 'Até o dia seguinte do sábado sétimo contareis cinquenta dias; então oferecereis nova oferta de cereais ao SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 23, 17, 'De vossas habitações trareis dois pães para oferta movida, que serão de dois décimos [de efa] de boa farinha, cozidos com levedura, por primícias ao SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 23, 18, 'E oferecereis com o pão sete cordeiros de ano sem defeito, e um bezerro das vacas e dois carneiros: serão holocausto ao SENHOR, com sua oferta de cereais e suas libações; oferta acesa de suave cheiro ao SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 23, 19, 'Oferecereis também um macho de bode por expiação; e dois cordeiros de ano em sacrifício pacífico.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 23, 20, 'E o sacerdote os moverá em oferta movida diante do SENHOR, com o pão das primícias, e os dois cordeiros: serão coisa sagrada do SENHOR para o sacerdote.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 23, 21, 'E convocareis neste mesmo dia; vos será santa convocação: nenhuma obra servil fareis: estatuto perpétuo em todas as vossas habitações por vossas gerações.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 23, 22, 'E quando ceifardes a colheita de vossa terra, não acabarás de ceifar o canto de tua plantação, nem espigarás tua colheita; para o pobre, e para o estrangeiro a deixarás: Eu sou o SENHOR vosso Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 23, 23, 'E falou o SENHOR a Moisés, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 23, 24, 'Fala aos filhos de Israel, e dize-lhes: No mês sétimo, ao primeiro do mês tereis sábado, uma comemoração ao são de trombetas, e uma santa convocação.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 23, 25, 'Nenhuma obra servil fareis; e oferecereis oferta acesa ao SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 23, 26, 'E falou o SENHOR a Moisés, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 23, 27, 'Porém aos dez deste mês sétimo será o dia das expiações: tereis santa convocação, e afligireis vossas almas, e oferecereis oferta acesa ao SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 23, 28, 'Nenhuma obra fareis neste mesmo dia; porque é dia de expiações, para reconciliar-vos diante do SENHOR vosso Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 23, 29, 'Porque toda pessoa que não se afligir neste mesmo dia, será eliminada de seus povos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 23, 30, 'E qualquer pessoa que fizer obra alguma neste mesmo dia, eu destruirei a tal pessoa dentre seu povo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 23, 31, 'Nenhuma obra fareis: estatuto perpétuo é por vossas gerações em todas as vossas habitações.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 23, 32, 'Sábado de repouso será a vós, e afligireis vossas almas, começando aos nove do mês na tarde: de tarde a tarde descansareis vosso sábado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 23, 33, 'E falou o SENHOR a Moisés, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 23, 34, 'Fala aos filhos de Israel, e dize-lhes: Aos quinze dias deste mês sétimo será a solenidade das cabanas ao SENHOR por sete dias.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 23, 35, 'O primeiro dia haverá santa convocação: nenhuma obra servil fareis.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 23, 36, 'Sete dias oferecereis oferta acesa ao SENHOR: o oitavo dia tereis santa convocação, e oferecereis oferta acesa ao SENHOR: é festa: nenhuma obra servil fareis.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 23, 37, 'Estas são as solenidades do SENHOR, às que convocareis santas reuniões, para oferecer oferta acesa ao SENHOR, holocausto e oferta de cereais, sacrifício e libações, cada coisa em seu tempo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 23, 38, 'Além disso dos sábados do SENHOR e além de vossos presentes, e a mais de todos vossos votos, e além de todas as vossas ofertas voluntárias, que dareis ao SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 23, 39, 'Porém aos quinze do mês sétimo, quando houverdes recolhido o fruto da terra, fareis festa ao SENHOR por sete dias: o primeiro dia será sábado; sábado será também o oitavo dia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 23, 40, 'E tomareis o primeiro dia galhos das mais belas árvores, ramos de palmeiras, e ramos de árvores frondosas, e salgueiros dos ribeiros; e vos regozijareis diante do SENHOR vosso Deus por sete dias.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 23, 41, 'E lhe fareis festa ao SENHOR por sete dias cada ano; será estatuto perpétuo por vossas gerações; no mês sétimo a fareis.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 23, 42, 'Em cabanas habitareis sete dias: todo natural de Israel habitará em cabanas;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 23, 43, 'Para que saibam vossos descendentes que em cabanas fiz eu habitar aos filhos de Israel, quando os tirei da terra do Egito: Eu sou o SENHOR vosso Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 23, 44, 'Assim falou Moisés aos filhos de Israel sobre as solenidades do SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 24, 1, 'E falou o SENHOR a Moisés, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 24, 2, 'Manda aos filhos de Israel que te tragam azeite de olivas claro, prensado, para a luminária, para fazer arder as lâmpadas continuamente.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 24, 3, 'Fora do véu do testemunho, no tabernáculo do testemunho, as preparará Arão desde a tarde até a manhã diante do SENHOR, continuamente: estatuto perpétuo por vossas gerações.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 24, 4, 'Sobre o candelabro limpo porá sempre em ordem as lâmpadas diante do SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 24, 5, 'E tomarás boa farinha, e cozerás dela doze tortas; cada torta será de dois décimos [de efa] .'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 24, 6, 'E as porás em duas fileiras, seis em cada fileira, sobre a mesa limpa diante do SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 24, 7, 'Porás também sobre cada fileira incenso limpo, e será para o pão por incenso, oferta acesa ao SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 24, 8, 'Cada dia de sábado o porá continuamente em ordem diante do SENHOR, dos filhos de Israel por pacto perpétuo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 24, 9, 'E será de Arão e de seus filhos, os quais o comerão no lugar santo; porque é coisa muito santa para ele, das ofertas acendidas ao SENHOR, por estatuto perpétuo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 24, 10, 'Naquela muita o filho de uma mulher israelita, o qual era filho de um egípcio, saiu entre os filhos de Israel; e o filho da israelita e um homem de Israel brigaram no acampamento:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 24, 11, 'E o filho da mulher israelita pronunciou o Nome, e amaldiçoou; então o levaram a Moisés. E sua mãe se chamava Selomite, filha de Dribi, da tribo de Dã.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 24, 12, 'E puseram-no no cárcere, até que lhes fosse sentenciado pela palavra do SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 24, 13, 'E o SENHOR falou a Moisés, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 24, 14, 'Traz o blasfemador para fora do acampamento, e todos os que o ouviram ponham suas mãos sobre a cabeça dele, e toda a congregação o apedreje.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 24, 15, 'E falarás aos filhos de Israel, dizendo: Qualquer um que amaldiçoar ao seu Deus, levará sobre si a sua iniquidade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 24, 16, 'E o que blasfemar o nome do SENHOR será morto; toda a congregação o apedrejará; tanto o estrangeiro como o natural, se blasfemar o Nome, que morra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 24, 17, 'Também o homem que fere de morte a qualquer pessoa será punido à morte.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 24, 18, 'Mas o que fere algum animal deverá restituí-lo; animal por animal.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 24, 19, 'E se alguém que causar lesão em seu próximo, segundo fez, assim lhe seja feito:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 24, 20, 'Fratura por fratura, olho por olho, dente por dente: segundo a lesão que houver feito a outro, assim se fará a ele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 24, 21, 'O que fere algum animal deverá restituí-lo; mas o que fere de morte a um homem será punido à morte.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 24, 22, 'Um mesmo regulamento tereis; como o estrangeiro, assim será o natural; porque eu sou o SENHOR, vosso Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 24, 23, 'E falou Moisés aos filhos de Israel, e eles trouxeram o blasfemador para fora do acampamento, e o apedrejaram. E os filhos de Israel fizeram segundo o que o SENHOR havia mandado a Moisés.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 25, 1, 'E o SENHOR falou a Moisés no monte Sinai, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 25, 2, 'Fala aos filhos de Israel, e dize-lhes: Quando houverdes entrado na terra que eu vos dou, a terra guardará um sábado ao SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 25, 3, 'Seis anos semearás a tua terra, e seis anos podarás a tua vinha, e colherás os seus frutos;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 25, 4, 'Mas no sétimo ano a terra terá um sábado de descanso, sábado ao SENHOR; não semearás a tua terra, nem podarás a tua vinha.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 25, 5, 'O que nascer de si mesmo na tua terra ceifada não ceifarás; e as uvas do teu vinhedo não vindimarás; será um ano de descanso para a terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 25, 6, 'Mas o sábado da terra vos será para comer a ti, e a teu servo, e a tua serva, e a tua criado, e a tua estrangeiro que morar contigo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 25, 7, 'E a teu animal, e à animal que houver em tua terra, será todo o fruto dela para comer.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 25, 8, 'E te hás de contar sete semanas de anos, sete vezes sete anos; de modo que os dias das sete semanas de anos virão a ser para ti quarenta e nove anos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 25, 9, 'Então farás passar a trombeta de júbilo no mês sétimo aos dez do mês; o dia da expiação fareis passar a trombeta por toda vossa terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 25, 10, 'E santificareis o ano cinquenta, e apregoareis liberdade na terra a todos os seus moradores: este vos será jubileu; e voltareis cada um à sua possessão, e cada qual voltará à sua família.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 25, 11, 'O ano dos cinquenta anos vos será jubileu: não semeareis, nem colhereis o que nascer de seu na terra, nem vindimareis seus vinhedos:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 25, 12, 'Porque é jubileu: santo será a vós; o produto da terra comereis.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 25, 13, 'Em este ano de jubileu voltareis cada um à sua possessão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 25, 14, 'E quando venderdes algo a vosso próximo, ou comprardes da mão de vosso próximo, não engane ninguém a seu irmão:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 25, 15, 'Conforme o número dos anos depois do jubileu comprarás de teu próximo; conforme o número dos anos dos frutos te venderá ele a ti.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 25, 16, 'Conforme a abundância dos anos aumentarás o preço, e conforme a diminuição dos anos diminuirás o preço; porque segundo o número dos rendimentos te há de vender ele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 25, 17, 'E não engane ninguém a seu próximo; mas terás temor de teu Deus: porque eu sou o SENHOR vosso Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 25, 18, 'Executai, pois, meus estatutos, e guardai meus regulamentos, e ponde-os por obra, e habitareis na terra seguros;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 25, 19, 'E a terra dará seu fruto, e comereis até fartura, e habitareis nela com segurança.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 25, 20, 'E se disserdes: Que comeremos no sétimo ano? eis que não temos de semear, nem temos de colher nossos frutos:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 25, 21, 'Então eu vos enviarei minha bênção no sexto ano, e fará fruto por três anos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 25, 22, 'E semeareis no ano oitavo, e comereis do fruto alheio; até o ano nono, até que venha seu fruto comereis do alheio.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 25, 23, 'E a terra não se venderá definitivamente, porque a terra minha é; que vós peregrinos e estrangeiros sois para comigo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 25, 24, 'Portanto, em toda a terra de vossa possessão, outorgareis remissão à terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 25, 25, 'Quando teu irmão empobrecer, e vender algo de sua possessão, virá o resgatador, seu próximo, e resgatará o que seu irmão houver vendido.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 25, 26, 'E quando o homem não tiver resgatador, se alcançar sua mão, e achar o que basta para seu resgate;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 25, 27, 'Então contará os anos de sua venda, e pagará o que restar ao homem a quem vendeu, e voltará à sua possessão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 25, 28, 'Mas se não alcançar sua mão o que basta para que volte a ele, o que vendeu estará em poder do que o comprou até o ano do jubileu; e ao jubileu sairá, e ele voltará à sua possessão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 25, 29, 'E o homem que vender casa de morada em cidade cercado, poderá resgatá-la até acabar-se o ano de sua venda: ano será o termo de se poder resgatar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 3, 'Levítico', 'Lv', 25, 30, 'E se não for resgatada dentro de ano inteiro, a casa que estiver na cidade murada ficará para sempre por daquele que a comprou, e para seus descendentes: não sairá no jubileu.')
